import{_ as e,c as l,o as r,ag as o}from"./chunks/framework.DJBJE7_Z.js";const f=JSON.parse('{"title":"ScribbleForge：企业级跨端实时协作白板SDK","description":"","frontmatter":{},"headers":[],"relativePath":"overview/product-overview.md","filePath":"overview/product-overview.md"}'),i={name:"overview/product-overview.md"};function s(n,t,g,d,a,c){return r(),l("div",null,t[0]||(t[0]=[o('<h1 id="scribbleforge-企业级跨端实时协作白板sdk" tabindex="-1">ScribbleForge：企业级跨端实时协作白板SDK <a class="header-anchor" href="#scribbleforge-企业级跨端实时协作白板sdk" aria-label="Permalink to &quot;ScribbleForge：企业级跨端实时协作白板SDK&quot;">​</a></h1><p>ScribbleForge 是一款领先的企业级<strong>跨端实时协作白板SDK</strong>，它集成了全面的白板协作工具、文档同步展示以及灵活的自定义插件管理系统。ScribbleForge 旨在为开发者提供一个强大、易用且高度可定制的互动白板解决方案，助力构建下一代协作应用。</p><h2 id="核心功能模块" tabindex="-1">核心功能模块 <a class="header-anchor" href="#核心功能模块" aria-label="Permalink to &quot;核心功能模块&quot;">​</a></h2><p>ScribbleForge 的核心功能覆盖了从基础绘图到复杂文档处理和实时同步的广泛需求，主要包括：</p><ol><li><p><strong>实时白板 (@netless/forge-whiteboard)</strong></p><ul><li><strong>多样化绘制工具</strong>：支持自由曲线、矩形、直线、箭头、文本、椭圆、三角形等多种绘制工具。</li><li><strong>专业工具集</strong>：包含擦除器、激光笔、选择器和拖动工具，满足专业用户的操作需求。</li><li><strong>丰富的样式配置</strong>：提供描边颜色、填充颜色、字体、线条宽度和虚线样式等高度自定义的设置。</li><li><strong>多页面管理</strong>：支持页面的添加、删除、跳转、复制和清空，方便组织和管理复杂内容。</li><li><strong>细粒度权限控制</strong>：强大的权限系统，确保协作过程的安全与可控。</li><li><strong>实时相机控制</strong>：支持缩放、拖动和边界限制，提供流畅且可控的用户视角体验。</li></ul></li><li><p><strong>文档处理系统</strong></p><ul><li><strong>PDF 文档 (@netless/forge-pdf-doc)</strong>：基于 <code>pdfjs-dist</code> 实现高质量的 PDF 文档渲染，并支持实时的标注和协作编辑。</li><li><strong>图像文档 (@netless/forge-imagery-doc)</strong>：支持图片文档的查看与协作式标注，让团队能直接在图像上沟通。</li><li><strong>演示文稿 (@netless/forge-slide)</strong>：集成 <code>@netless/slide</code>，提供流畅的幻灯片展示功能，支持课件或演示的同步。</li></ul></li><li><p><strong>多媒体播放器 (@netless/forge-media-player)</strong></p><ul><li><strong>HLS 视频流播放</strong>：通过 <code>hls.js</code> 支持 HLS 视频流的稳定播放。</li><li><strong>统一播放器界面</strong>：基于 <code>Plyr</code> 提供简洁一致的播放器界面。</li><li><strong>实时同步播放状态</strong>：确保所有参与者都能同步观看视频，并实时同步播放进度和控制。</li></ul></li><li><p><strong>房间管理系统 (@netless/forge-room)</strong></p><ul><li><strong>应用生命周期管理</strong>：负责协作房间的创建、销毁等全生命周期事件的管理。</li><li><strong>用户管理与权限控制</strong>：集中管理用户身份及其在房间内的各种权限。</li><li><strong>数据备份与恢复</strong>：提供可靠的数据备份与恢复机制，保障数据安全与持续性。</li><li><strong>回放功能支持</strong>：支持对整个协作过程进行录制和回放，便于回顾和审计。</li></ul></li><li><p><strong>窗口管理器 (@netless/forge-window-manager)</strong></p><ul><li><strong>多窗口应用协调</strong>：支持多个应用窗口在同一协作空间内协同工作，提升信息整合效率。</li><li><strong>窗口层级与布局管理</strong>：提供灵活的窗口层级和布局管理能力，满足复杂界面设计需求。</li></ul></li></ol><hr><h2 id="技术优势" tabindex="-1">技术优势 <a class="header-anchor" href="#技术优势" aria-label="Permalink to &quot;技术优势&quot;">​</a></h2><p>ScribbleForge 在技术层面具备多项优势，确保其高性能、高可靠性和灵活性：</p><ol><li><p><strong>现代化架构设计</strong></p><ul><li><strong>Monorepo 架构</strong>：采用 <code>pnpm workspace</code> 进行多包依赖管理，优化项目结构和依赖关系，提高开发效率。</li><li><strong>模块化设计</strong>：每个功能模块独立打包，支持按需组合使用，极大提升了灵活性和可扩展性。</li><li><strong>TypeScript 全栈</strong>：全程使用 TypeScript，提供强大的类型安全保障，显著减少运行时错误，提升代码质量。</li></ul></li><li><p><strong>强大的实时协作能力</strong></p><ul><li><strong>Y.js CRDT</strong>：运用业界领先的 <strong>Conflict-free Replicated Data Types (CRDT)</strong> 算法，实现无冲突的数据同步、离线操作支持以及精确的操作历史追踪。</li><li><strong>多信令通道支持</strong>：支持 RTM Provider (Agora RTM 2.1) 和 Socket.IO Provider，提供灵活的信令传输方案，适应不同网络环境。</li><li><strong>EventEmitter3</strong>：采用高效的事件驱动架构，优化事件处理性能，确保实时响应。</li></ul></li><li><p><strong>高性能图形渲染</strong></p><ul><li><strong>Paper.js 集成</strong>：使用 <code>Paper.js</code> 矢量图形库，提供流畅、精美的绘制体验。</li><li><strong>Perfect-freehand</strong>：通过 <code>Perfect-freehand</code> 算法优化手写笔迹，使书写更加自然流畅。</li><li><strong>高效相机系统</strong>：优化的视口管理和渲染技术，确保高效的图形渲染能力。</li></ul></li><li><p><strong>企业级权限管理</strong></p><ul><li><strong>细粒度权限控制</strong>：提供如 <code>draw</code> (绘制)、<code>editSelf</code> (编辑自己元素)、<code>editOthers</code> (编辑他人元素)、<code>mainView</code> (主视角控制) 等精细化的权限标识，满足复杂的企业级权限管理需求。</li></ul></li><li><p><strong>灵活的存储策略</strong></p><ul><li><strong>LocalForage</strong>：利用 <code>LocalForage</code> 实现智能本地存储，支持 IndexedDB、WebSQL 和 localStorage，兼顾性能和兼容性。</li><li><strong>数据备份机制</strong>：提供自动数据备份和恢复功能，保障数据持久性和安全性。</li><li><strong>持久化同步</strong>：房间状态能够被持久化保存，确保数据不丢失。</li></ul></li><li><p><strong>现代化构建工具链</strong></p><ul><li><strong>ESBuild</strong>：采用 <code>ESBuild</code> 进行极速构建和打包，大幅提升开发效率。</li><li><strong>TypeScript 编译</strong>：支持 TypeScript 编译，进行类型检查和声明文件生成。</li><li><strong>多格式输出</strong>：支持 CommonJS 和 ESM 双格式输出，满足不同项目集成需求。</li><li><strong>实时开发</strong>：<code>onChange</code> 文件监听支持热更新，加速开发迭代过程。</li></ul></li><li><p><strong>专业的 PDF 处理</strong></p><ul><li><strong>最新 PDF.js 版本</strong>：基于 <code>PDF.js 5.1.91</code> 的最新技术，提供高质量的 PDF 渲染。</li><li><strong>支持 PDF 标注和协作编辑</strong>：允许用户在 PDF 文档上进行标注和实时协作编辑。</li><li><strong>高质量矢量渲染</strong>：确保 PDF 内容以矢量图形的高质量形式呈现。</li></ul></li><li><p><strong>跨平台兼容性</strong></p><ul><li><strong>Web 标准 API</strong>：基于 Web 标准 API 构建，确保广泛的浏览器兼容性。</li><li><strong>响应式设计支持</strong>：支持响应式设计，能够适配不同屏幕尺寸。</li><li><strong>移动端触摸优化</strong>：针对移动端触摸操作进行深度优化，提供流畅的移动协作体验。</li></ul></li></ol><hr><h2 id="技术栈总结" tabindex="-1">技术栈总结 <a class="header-anchor" href="#技术栈总结" aria-label="Permalink to &quot;技术栈总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">技术领域</th><th style="text-align:left;">采用技术</th><th style="text-align:left;">优势</th></tr></thead><tbody><tr><td style="text-align:left;">实时协作</td><td style="text-align:left;">Y.js + EventEmitter3</td><td style="text-align:left;">CRDT 算法，无冲突同步</td></tr><tr><td style="text-align:left;">图形渲染</td><td style="text-align:left;">Paper.js + Perfect-freehand</td><td style="text-align:left;">高性能矢量图形</td></tr><tr><td style="text-align:left;">构建工具</td><td style="text-align:left;">ESBuild + TypeScript</td><td style="text-align:left;">极速构建，类型安全</td></tr><tr><td style="text-align:left;">存储方案</td><td style="text-align:left;">LocalForage + 自研备份</td><td style="text-align:left;">智能存储，数据可靠</td></tr><tr><td style="text-align:left;">多媒体</td><td style="text-align:left;">PDF.js + HLS.js + Plyr</td><td style="text-align:left;">专业文档和视频处理</td></tr><tr><td style="text-align:left;">包管理</td><td style="text-align:left;">pnpm workspace</td><td style="text-align:left;">高效依赖管理</td></tr></tbody></table><p>ScribbleForge 在实时协作、图形渲染、权限管理等核心技术领域都采用了业界先进的解决方案，具备了构建企业级白板协作平台的坚实技术基础。</p>',13)]))}const u=e(i,[["render",s]]);export{f as __pageData,u as default};
